local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local kTool = CS.Engine.Lib.KTool
local RawImageAlterable = CS.Engine.UI.RawImageAlterable
local UIModule = CS.Engine.UI.UIModule
local CAT_GET_POPUP_FINISH = "CAT_GET_POPUP_FINISH"
------------ import ------------
---@type UIBattlingTools
local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")

------------ import ------------

------------ define ------------
------------ define ------------

---@class UIGetCardSkillDialog
---@field LabelNode                        UnityEngine.RectTransform @子节点
---@field Container                        UnityEngine.RectTransform @容器
---@field TextTitle                        UnityEngine.UI.Text @技能名称
---@field ImgIcon                        UnityEngine.UI.RawImage @技能icon
---@field NameText2                        UnityEngine.UI.Text @猫种名称
---@field TypeText1                        UnityEngine.UI.Text @通过什么方式解锁
local UIGetCardSkillDialog = Class("UIGetCardSkillDialog")

function UIGetCardSkillDialog:__init()
end

function UIGetCardSkillDialog:__delete()
    self.controller = nil
end

function UIGetCardSkillDialog:Awake()
    kTool.SetActive(self.LabelNode.gameObject, false)
    kTool.GetOrAddComponent(self.ImgIcon.gameObject, typeof(RawImageAlterable))
end


function UIGetCardSkillDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument
        if not isNull(argument.parameters) then
            local text1 = tostring(argument.parameters.text1)
            local text2 = tostring(argument.parameters.text2)

            local genId = checkInt(argument.parameters.genId)
            --有加成的时候会传基因ID
            if genId > 0 then
                local vo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", genId)
                if not vo then
                    return
                end
                --有加成数据
                if vo.variationKindList and #vo.variationKindList > 0 then
                    kTool.SetActive(self.ForceAdditionDetails, true)
                    self:FillAttrs(vo)
                end
            else
                kTool.SetActive(self.CardSkillDetails, true)
                ----合卡技的id
                local skillId = checkInt(argument.parameters.skillId)
                ---@type UnitSkillVo
                local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(skillId)
                local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(vo.skillId, 1)
                CfUtils.FillText(self.TextTitle, skillVo.skillName)
                kTool.SetActive(self.TypeText1.transform.parent, true)
                CfUtils.FillImage(self.ImgIcon, vo.photo2Path)
                self:FillTag(vo)
            end

            CfUtils.SetUISwitchText(self.TextName, genId > 0 and 2 or 1)
            CfUtils.FillText(self.TypeText1, text1)
            CfUtils.FillText(self.NameText2, text2)
        end
    end))
    return coWait
end

function UIGetCardSkillDialog:FillAttrs(vo)
    if not vo then
        return
    end
    for k, v in pairs(vo.variationKindList) do
        local go = self.ForceAdditionDetails.transform:Find("go"..k) 
        if not go then
            go = CfUtils.InstantiateGo(self.CatAttributeNode, self.ForceAdditionDetails)
            go.name = "go"..k
        end        
        kTool.SetActive(go, true)
        self:FillAttrNode(go, v, k, vo.variationNumList[k])
    end
end

function UIGetCardSkillDialog:FillAttrNode(go, data, ind, num)
    if not go or not data then
        return
    end
    num = checkNumber(num)

    local scr = CfUtils.GetLuaScr(go, 'Game.CatHouse.Interaction.CatHouseInteractionAttributeNode')
    if scr then
        ---属性加城与技能数据处理
        local attributeVo = CardConfMgr:GetInstance():GetBasicAttrByBasicAttrAdditionId(data)
        if attributeVo then
            scr:FreshBaseUI({ name = attributeVo.name, picture = attributeVo.icon }, ind)
            scr:FreshAttrValue({ num = '+' .. attribute_format(attributeVo.isConversion, num) })
        end  
    end
end

---FillTag
---@param vo UnitSkillVo
function UIGetCardSkillDialog:FillTag(vo)
    local t = {}
    if vo.typeOne ~= "" then
        table.insert(t, {
            name = vo.typeOne,
            status = vo.typeOneColor,
        })
    end

    if vo.typeTwo ~= "" then
        table.insert(t, {
            name = vo.typeTwo,
            status = vo.typeTwoColor,
        })
    end

    for k, v in pairs(t) do
        local go = self.Container.transform:Find("cell"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.LabelNode.gameObject, self.Container.gameObject)
            go.name = "cell"..k
        end
        CfUtils.FillText(go.transform:Find("Text"), v.name)
        --CfUtils.SetUISwitchImage(go, v.status)
        kTool.SetActive(go, true)
    end
end


function UIGetCardSkillDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
        if component then
            local data = component:GetPopData()
            if data then
                Events.Broadcast(CAT_GET_POPUP_FINISH, data)
            end
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIGetCardSkillDialog